mapper.select:
SELECT 
  FROM sys52_specific_menu_link
 WHERE sys52_specific_work_cd = #{specificWorkCd}
   AND sys52_company_id       = #{companyId}
 ORDER BY sys52_link_cd

mapper.update:
UPDATE sys52_specific_menu_link
   SET sys52_link_cd = #{req.linkCd},
       sys52_note    = #{req.note}
 WHERE sys52_specific_menu_link_id = #{req.specificMenuLinkId}
   AND sys52_company_id            = #{companyId}

mapper.delete:
DELETE FROM sys52_specific_menu_link
 WHERE sys52_company_id = #{companyId}
   AND sys52_specific_menu_link_id IN
#{id}
